SELECT 3642 AS no_var, COUNT(*) AS baris FROM (SELECT IFNULL((SELECT CASE WHEN p.jenis_kelamin = 'P' THEN 'calon suami' WHEN p.jenis_kelamin = 'L' THEN 'calon istri' ELSE 'calon pasangan' END
  FROM perkara_pihak1 pp JOIN pihak p ON p.id = pp.pihak_id WHERE pp.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, pp.id) = 1 LIMIT 1), 'calon pasangan') AS data) AS uji_3642;
SELECT 3643 AS no_var, COUNT(*) AS baris FROM (SELECT IFNULL((SELECT TIMESTAMPDIFF(YEAR, p.tanggal_lahir, pr.tanggal_pendaftaran)
  FROM perkara_pihak1 pp JOIN pihak p ON p.id = pp.pihak_id JOIN perkara pr ON pr.perkara_id = pp.perkara_id
  WHERE pp.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, pp.id) = 1 AND p.tanggal_lahir IS NOT NULL AND p.tanggal_lahir <> '0000-00-00' LIMIT 1), '') AS data) AS uji_3643;
SELECT 3673 AS no_var, COUNT(*) AS baris FROM (SELECT IFNULL((SELECT CASE WHEN COUNT(*) >= 2 THEN CONCAT('Pemohon I (', MAX(CASE WHEN aps_badilag.isian_rtf_pihak_peringkat(1, pp.id) = 1 THEN p.nama END), ') dan Pemohon II (', MAX(CASE WHEN aps_badilag.isian_rtf_pihak_peringkat(1, pp.id) = 2 THEN p.nama END), ')')
  WHEN COUNT(*) = 1 THEN MAX(p.nama) ELSE NULL END FROM perkara_pihak1 pp JOIN pihak p ON p.id = pp.pihak_id WHERE pp.perkara_id = @pid), 'para Pemohon') AS data) AS uji_3673;
