SELECT 7078 AS no_var, COUNT(*) AS baris FROM (SELECT 
  CASE 
    WHEN LOCATE('E-COURT', "0") > 0 THEN ''
    WHEN alur_perkara_id = 16 AND aps_badilag.isian_rtf_pihak_peringkat(1, perkara_pihak1.id) = 2 THEN "0 I,"
    ELSE "0,"
  END as data
FROM perkara
JOIN perkara_pihak1 ON perkara.perkara_id = perkara_pihak1.perkara_id
WHERE perkara.perkara_id = @pid) AS uji_7078;
SELECT 8129 AS no_var, COUNT(*) AS baris FROM (SELECT MIN(r.tanggal_relaas) AS data FROM perkara_pelaksanaan_relaas r JOIN perkara_pihak2 p ON p.perkara_id = r.perkara_id AND p.pihak_id = r.pihak_id AND aps_badilag.isian_rtf_pihak_peringkat(2, p.id) = 1 WHERE r.perkara_id = @pid AND r.tanggal_relaas > '1900-01-01' HAVING COUNT(*) > 0) AS uji_8129;
SELECT 8510 AS no_var, COUNT(*) AS baris FROM (SELECT
  CASE
    WHEN y.jp IN (346, 347) AND y.k = 'PNS' THEN
      "<br>Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang Pegawai Negeri Sipil, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    WHEN y.jp IN (346, 347) AND y.k = 'PPPK' THEN
      "<br>Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang Aparatur Sipil Negara (PPPK), 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    WHEN y.jp IN (346, 347) AND y.k = 'POLRI' THEN
      "<br>Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang aparat Kepolisian Negara Republik Indonesia, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    WHEN y.jp IN (346, 347) AND y.k = 'TNI' THEN
      "<br>Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang aparat Tentara Nasional Indonesia, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    WHEN y.jp IN (346, 347) AND y.k IN ('BUMN', 'BUMD') THEN
      "Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang seorang Pegawai BUMN/BUMD, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    WHEN y.jp IN (346, 347) AND y.k = 'DESA' THEN
      "Bahwa untuk memenuhi pensyaratan mengajukan perceraian dalam status sebagai seorang aparat Desa, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;"
    ELSE ''
  END
  AS data
FROM (
  SELECT x.jp,
    CASE WHEN TRIM(IFNULL(x.asli, '')) = '' THEN 'KOSONG' WHEN x.asli IN ('Pegawai Negeri Sipil') THEN 'PNS' WHEN x.asli IN ('POLRI', 'Polisi', 'polwan') THEN 'POLRI' WHEN x.asli IN ('Tentara Nasional Indonesia', 'TNI', 'Tentara') THEN 'TNI' WHEN x.asli IN ('Pegawai BUMN/BUMD', 'Pegawai BUMN', 'Pegawai BUMD', 'BUMN/BUMD', 'BUMN', 'BUMD') THEN 'BUMN' WHEN x.asli IN ('Kepala Desa', 'Kades', 'aparat desa', 'sekretaris desa', 'Sekdes') THEN 'DESA' WHEN x.t REGEXP '[[:<:]]pensi|purnawirawan|[[:<:]]purna[[:space:]]*(bakti|tugas)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](mantan|bekas|eks|ex)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](istri|isteri|suami|anak|janda|duda)[[:space:]]+(dari[[:space:]]+|seorang[[:space:]]+)?(anggota|pns|tni|polri|polisi|asn|tentara|pegawai|prajurit|almarhum|alm)[[:>:]]|[[:<:]](persit|bhayangkari)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]bukan[[:>:]]|[[:<:]]non[[:space:]-]*(pns|asn)[[:>:]]|[[:<:]]pbpns[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]cpns[[:>:]]|calon[[:space:]]+(pegawai[[:space:]]+nege?ri|pns|asn)' THEN 'BUKAN' WHEN x.t REGEXP 'paruh[[:space:]]*waktu' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pppk|p3k|nipppk)[[:>:]]|perjanjian[[:space:]]+kerja' THEN 'PPPK' WHEN x.t REGEXP '[[:<:]]hon(or|er|oner|arer)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](kontrak|sukarela|magang|phl|thl|ptt)[[:>:]]|outsourc|harian[[:space:]]+lepas|tenaga[[:space:]]+harian' THEN 'BUKAN' WHEN x.t REGEXP 'swasta|[[:<:]](satpam|security|cleaning|spbu|agen|brilink)[[:>:]]|[[:<:]]bri[[:space:]]*link[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pns|asn)[[:>:]]|pegawai[[:space:]]+nege?ri|aparatur[[:space:]]+sipil' THEN 'PNS' WHEN x.t REGEXP 'pamong[[:space:]]*praja|[[:<:]]sat[[:space:]]*pol[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](polri|polisi|polwan|kepolisian|brimob|bhabinkamtibmas|bhabin|polres|polresta|polsek|polda|bripka|brigpol|brigadir|briptu|bripda|aiptu|aipda|ipda|iptu|kompol|akbp)[[:>:]]' THEN 'POLRI' WHEN x.t REGEXP '[[:<:]](tni|tentara|prajurit|babinsa|kod