    WHEN y.jp IN (346, 347) AND y.k = 'TNI' THEN
      "<br>Sebelum proses pemeriksaan perkara 0 sebagai seorang aparat Tentara Nasional Indonesia, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;<strong>Z CROSS</strong>"
    WHEN y.jp IN (346, 347) AND y.k = 'DESA' THEN
      "Sebelum proses pemeriksaan perkara 0 sebagai seorang aparat Desa, 0 telah memperoleh izin dari atasan berdasarkan Surat Izin Nomor 0 tanggal 0 yang dikeluarkan oleh 0;<strong>Z CROSS</strong>"
    ELSE ''
  END
  ,
  CASE
    WHEN y.jp IN (346, 347) AND z.k = 'PNS' THEN
      "<br>Sebelum proses pemeriksaan perkara, 0 mencatat bahwa 0 berstatus sebagai seorang Pegawai Negeri Sipil, sehingga sesuai ketentuan Pasal 3 ayat (2) dan ayat (3) Peraturan Pemerintah Nomor 10 Tahun 1983 sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 45 Tahun 1990 tentang Izin Perkawinan dan Perceraian bagi Pegawai Negeri Sipil, 0 berkewajiban mengajukan surat permintaan izin atau pemberitahuan adanya gugatan perceraian secara tertulis kepada atasannya untuk mendapatkan surat keterangan;"
    WHEN y.jp IN (346, 347) AND z.k = 'PPPK' THEN
      "<br>Sebelum proses pemeriksaan perkara, 0 mencatat bahwa 0 berstatus sebagai seorang Aparatur Sipil Negara (PPPK), sehingga sesuai ketentuan Pasal 3 ayat (2) dan ayat (3) Peraturan Pemerintah Nomor 10 Tahun 1983 sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 45 Tahun 1990 tentang Izin Perkawinan dan Perceraian bagi Pegawai Negeri Sipil, 0 berkewajiban mengajukan surat permintaan izin atau pemberitahuan adanya gugatan perceraian secara tertulis kepada atasannya untuk mendapatkan surat keterangan;"
    WHEN y.jp IN (346, 347) AND z.k = 'POLRI' THEN
      "<br>Sebelum proses pemeriksaan perkara, 0 mencatat bahwa 0 adalah seorang anggota Kepolisian Negara Republik Indonesia (POLRI), sehingga sesuai ketentuan Peraturan Kepala Kepolisian Negara Republik Indonesia Nomor 9 Tahun 2010, 0 berkewajiban menyampaikan pemberitahuan adanya gugatan perceraian tersebut secara tertulis kepada atasannya;"
    WHEN y.jp IN (346, 347) AND z.k = 'TNI' THEN
      "<br>Sebelum proses pemeriksaan perkara, 0 mencatat bahwa 0 adalah seorang anggota Tentara Nasional Indonesia (TNI), sehingga sesuai ketentuan Surat Keputusan Menteri Pertahanan dan Keamanan/Panglima Angkatan Bersenjata Nomor Kep/01/I/1980, 0 berkewajiban menyampaikan pemberitahuan adanya gugatan perceraian tersebut secara tertulis kepada atasannya;"
    ELSE ''
  END
) AS data
FROM (
  SELECT x.jp,
    CASE WHEN TRIM(IFNULL(x.asli, '')) = '' THEN 'KOSONG' WHEN x.asli IN ('Pegawai Negeri Sipil') THEN 'PNS' WHEN x.asli IN ('POLRI', 'Polisi', 'polwan') THEN 'POLRI' WHEN x.asli IN ('Tentara Nasional Indonesia', 'TNI', 'Tentara') THEN 'TNI' WHEN x.asli IN ('Pegawai BUMN/BUMD', 'Pegawai BUMN', 'Pegawai BUMD', 'BUMN/BUMD', 'BUMN', 'BUMD') THEN 'BUMN' WHEN x.asli IN ('Kepala Desa', 'Kades', 'aparat desa', 'sekretaris desa', 'Sekdes') THEN 'DESA' WHEN x.t REGEXP '[[:<:]]pensi|purnawirawan|[[:<:]]purna[[:space:]]*(bakti|tugas)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](mantan|bekas|eks|ex)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](istri|isteri|suami|anak|janda|duda)[[:space:]]+(dari[[:space:]]+|seorang[[:space:]]+)?(anggota|pns|tni|polri|polisi|asn|tentara|pegawai|prajurit|almarhum|alm)[[:>:]]|[[:<:]](persit|bhayangkari)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]bukan[[:>:]]|[[:<:]]non[[:space:]-]*(pns|asn)[[:>:]]|[[:<:]]pbpns[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]cpns[[:>:]]|calon[[:space:]]+(pegawai[[:space:]]+nege?ri|pns|asn)' THEN 'BUKAN' WHEN x.t REGEXP 'paruh[[:space:]]*waktu' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pppk|p3k|nipppk)[[:>:]]|perjanjian[[:space:]]+kerja' THEN 'PPPK' WHEN x.t REGEXP '[[:<:]]hon(or|er|oner|arer)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](kontrak|sukarela|magang|phl|thl|ptt)[[:>:]]|outsourc|harian[[:space:]]+lepas|tenaga[[:space:]]+harian' THEN 'BUKAN' WHEN x.t REGEXP 'swasta|[[:<:]](satpam|security|cleaning|spbu|agen|brilink)[[:>:]]|[[:<:]]bri[[:space:]]*link[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pns|asn)[[:>:]]|pegawai[[:space:]]+nege?ri|aparatur[[:space:]]+sipil' THEN 'PNS' WHEN x.t REGEXP 'pamong[[:space:]]*praja|[[:<:]]sat[[:space:]]*pol[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](polri|polisi|polwan|kepolisian|brimob|bhabinkamtibmas|bhabin|polres|polresta|polsek|polda|bripka|brigpol|brigadir|briptu|bripda|aiptu|aipda|ipda|iptu|kompol|akbp)[[:>:]]' THEN 'POLRI' WHEN x.t REGEXP '[[:<:]](tni|tentara|prajurit|babinsa|kodim|koramil|korem|kodam|lanal|lanud|yonif|marinir|kostrad|kopassus|serda|sertu|serka|serma|kopda|koptu|kopka|praka|pratu|prada|letda|lettu)[[:>:]]|angkatan[[:space:]]+(darat|laut|udara)' THEN 'TNI' WHEN x.t REGEXP '[[:<:]](bumn|persero|pertamina|pln|telkom|bri|bni|btn|bsi|pegadaian|pelni|kai|taspen|asabri|pelindo|bulog|ptpn|perhutani|asdp|damri|pgn)[[:>:]]|bank[[:space:]]+(mandiri|rakyat[[:space:]]+indonesia|negara[[:space:]]+indonesia|tabungan[[:space:]]+negara|syariah[[:space:]]+indonesia)|kereta[[:space:]]+api|pos[[:space:]]+indonesia|kantor[[:space:]]+pos|[[:<:]]pt[.]?[[:space:]]*pos[[:>:]]|jasa[[:space:]]+raharja|angkasa[[:space:]]+pura|garuda[[:space:]]+indonesia|semen[[:space:]]+tonasa|permodalan[[:space:]]+nasio[a-z]*[[:space:]]+madani|[[:<:]]pnm[[:>:]]' THEN 'BUMN' WHEN x.t REGEXP '[[:<:]](bumd|pdam|perumda|perusda|perseroda|bsg)[[:>:]]|bank[[:space:]]+(sulteng|daerah|sulutgo|sulselbar|bpd)|[[:<:]]bpd[[:space:]]+sulteng|perusahaan[[:space:]]+daerah' THEN 'BUMD' WHEN x.t REGEXP 'kepala[[:space:]]+desa|[[:<:]]kades[[:>:]]|sekretaris[[:space:]]+desa|[[:<:]]sekdes[[:>:]]|aparat(ur)?[[:space:]]+(kantor[[:space:]]+|balai[[:space:]]+)?desa|perangkat[[:space:]]+desa|[[:<:]]kaur[[:>:]]|kepala[[:space:]]+seksi.*desa|[[:<:]]kasi[[:>:]].*desa|kepala[[:space:]]+dusun|[[:<:]]kadus[[:>:]]' THEN 'DESA' ELSE 'LAIN' END AS k
  FROM (
    SELECT p.jenis_perkara_id AS jp, b.pekerjaan AS asli, LOWER(CONVERT(IFNULL(b.pekerjaan, '') USING utf8)) AS t
    FROM perkara_pihak1 a
      JOIN pihak b ON a.pihak_id = b.id
      LEFT JOIN perkara p ON a.perkara_id = p.perkara_id
    WHERE aps_badilag.isian_rtf_pihak_peringkat(1, a.id) = 1 AND a.perkara_id = @pid
  ) x
) y
LEFT JOIN (
  SELECT CASE WHEN TRIM(IFNULL(x.asli, '')) = '' THEN 'KOSONG' WHEN x.asli IN ('Pegawai Negeri Sipil') THEN 'PNS' WHEN x.asli IN ('POLRI', 'Polisi', 'polwan') THEN 'POLRI' WHEN x.asli IN ('Tentara Nasional Indonesia', 'TNI', 'Tentara') THEN 'TNI' WHEN x.asli IN ('Pegawai BUMN/BUMD', 'Pegawai BUMN', 'Pegawai BUMD', 'BUMN/BUMD', 'BUMN', 'BUMD') THEN 'BUMN' WHEN x.asli IN ('Kepala Desa', 'Kades', 'aparat desa', 'sekretaris desa', 'Sekdes') THEN 'DESA' WHEN x.t REGEXP '[[:<:]]pensi|purnawirawan|[[:<:]]purna[[:space:]]*(bakti|tugas)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](mantan|bekas|eks|ex)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](istri|isteri|suami|anak|janda|duda)[[:space:]]+(dari[[:space:]]+|seorang[[:space:]]+)?(anggota|pns|tni|polri|polisi|asn|tentara|pegawai|prajurit|almarhum|alm)[[:>:]]|[[:<:]](persit|bhayangkari)[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]bukan[[:>:]]|[[:<:]]non[[:space:]-]*(pns|asn)[[:>:]]|[[:<:]]pbpns[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]]cpns[[:>:]]|calon[[:space:]]+(pegawai[[:space:]]+nege?ri|pns|asn)' THEN 'BUKAN' WHEN x.t REGEXP 'paruh[[:space:]]*waktu' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pppk|p3k|nipppk)[[:>:]]|perjanjian[[:space:]]+kerja' THEN 'PPPK' WHEN x.t REGEXP '[[:<:]]hon(or|er|oner|arer)' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](kontrak|sukarela|magang|phl|thl|ptt)[[:>:]]|outsourc|harian[[:space:]]+lepas|tenaga[[:space:]]+harian' THEN 'BUKAN' WHEN x.t REGEXP 'swasta|[[:<:]](satpam|security|cleaning|spbu|agen|brilink)[[:>:]]|[[:<:]]bri[[:space:]]*link[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](pns|asn)[[:>:]]|pegawai[[:space:]]+nege?ri|aparatur[[:space:]]+sipil' THEN 'PNS' WHEN x.t REGEXP 'pamong[[:space:]]*praja|[[:<:]]sat[[:space:]]*pol[[:>:]]' THEN 'BUKAN' WHEN x.t REGEXP '[[:<:]](polri|polisi|polwan|kepolisian|brimob|bhabinkamtibmas|bhabin|polres|polresta|polsek|polda|bripka|brigpol|brigadir|briptu|bripda|aiptu|aipda|ipda|iptu|kompol|akbp)[[:>:]]' THEN 'POLRI' WHEN x.t REGEXP '[[:<:]](tni|tentara|prajurit|babinsa|kodim|koramil|korem|kodam|lanal|lanud|yonif|marinir|kostrad|kopassus|serda|sertu|serka|serma|kopda|koptu|kopka|praka|pratu|prada|letda|lettu)[[:>:]]|angkatan[[:space:]]+(darat|laut|udara)' THEN 'TNI' WHEN x.t REGEXP '[[:<:]](bumn|persero|pertamina|pln|telkom|bri|bni|btn|bsi|pegadaian|pelni|kai|taspen|asabri|pelindo|bulog|ptpn|perhutani|asdp|damri|pgn)[[:>:]]|bank[[:space:]]+(mandiri|rakyat[[:space:]]+indonesia|negara[[:space:]]+indonesia|tabungan[[:space:]]+negara|syariah[[:space:]]+indonesia)|kereta[[:space:]]+api|pos[[:space:]]+indonesia|kantor[[:space:]]+pos|[[:<:]]pt[.]?[[:space:]]*pos[[:>:]]|jasa[[:space:]]+raharja|angkasa[[:space:]]+pura|garuda[[:space:]]+indonesia|semen[[:space:]]+tonasa|permodalan[[:space:]]+nasio[a-z]*[[:space:]]+madani|[[:<:]]pnm[[:>:]]' THEN 'BUMN' WHEN x.t REGEXP '[[:<:]](bumd|pdam|perumda|perusda|perseroda|bsg)[[:>:]]|bank[[:space:]]+(sulteng|daerah|sulutgo|sulselbar|bpd)|[[:<:]]bpd[[:space:]]+sulteng|perusahaan[[:space:]]+daerah' THEN 'BUMD' WHEN x.t REGEXP 'kepala[[:space:]]+desa|[[:<:]]kades[[:>:]]|sekretaris[[:space:]]+desa|[[:<:]]sekdes[[:>:]]|aparat(ur)?[[:space:]]+(kantor[[:space:]]+|balai[[:space:]]+)?desa|perangkat[[:space:]]+desa|[[:<:]]kaur[[:>:]]|kepala[[:space:]]+seksi.*desa|[[:<:]]kasi[[:>:]].*desa|kepala[[:space:]]+dusun|[[:<:]]kadus[[:>:]]' THEN 'DESA' ELSE 'LAIN' END AS k
  FROM (
    SELECT b2.pekerjaan AS asli, LOWER(CONVERT(IFNULL(b2.pekerjaan, '') USING utf8)) AS t
