SELECT 8890 AS no_var, COUNT(*) AS baris FROM (SELECT CASE WHEN p.jenis_perkara_id <> 346 THEN CONCAT("Menimbang, bahwa berdasarkan relaas panggilan nomor: 0 terbukti bahwa 0 bertempat tinggal di wilayah ", aps_badilag.isian_rtf_alamat("0"), " yang merupakan wilayah hukum 0, sebagaimana ketentuan Pasal 73 ayat (1) Undang-Undang Nomor 7 Tahun 1989 yang sudah diubah dengan Undang-Undang Nomor 3 tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 tentang Peradilan Agama, maka 0 telah tepat mengajukan perkaranya di 0;") WHEN IFNULL(t.kab, '') = '' OR EXISTS (SELECT 1 FROM perkara z JOIN perkara_pihak1 zp ON zp.perkara_id = z.perkara_id AND aps_badilag.isian_rtf_pihak_peringkat(1, zp.id) = 1 JOIN pihak zh ON zh.id = zp.pihak_id WHERE z.jenis_perkara_id = 347 AND zh.kabupaten = t.kab) THEN CONCAT("Menimbang, bahwa berdasarkan relaas panggilan nomor: 0 terbukti bahwa 0 bertempat tinggal di wilayah ", aps_badilag.isian_rtf_alamat("0"), " yang merupakan wilayah hukum 0, sebagaimana ketentuan Pasal 66 ayat (2) Undang-Undang Nomor 7 Tahun 1989 yang sudah diubah dengan Undang-Undang Nomor 3 tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 tentang Peradilan Agama, maka 0 telah tepat mengajukan perkaranya di 0;") ELSE CONCAT("[PERIKSA: menurut SIPP 0 bertempat tinggal di luar wilayah hukum 0; uraikan dasar pengecualian Pasal 66 ayat (2)/(3)] Menimbang, bahwa berdasarkan relaas panggilan nomor: 0 terbukti bahwa 0 bertempat tinggal di wilayah ", aps_badilag.isian_rtf_alamat("0"), " yang merupakan wilayah hukum 0, sebagaimana ketentuan Pasal 66 ayat (2) Undang-Undang Nomor 7 Tahun 1989 yang sudah diubah dengan Undang-Undang Nomor 3 tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 tentang Peradilan Agama, maka 0 telah tepat mengajukan perkaranya di 0;") END AS data FROM perkara p LEFT JOIN (SELECT x.perkara_id, MAX(y.kabupaten) AS kab FROM perkara_pihak2 x JOIN pihak y ON y.id = x.pihak_id WHERE x.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(2, x.id) = 1 GROUP BY x.perkara_id) t ON t.perkara_id = p.perkara_id WHERE p.perkara_id = @pid) AS uji_8890;
SELECT 9104 AS no_var, COUNT(*) AS baris FROM (SELECT CASE WHEN y.n IS NOT NULL AND LOWER(LEFT(y.n,3))='alm' THEN CONCAT(UPPER(LEFT(y.n,1)),SUBSTRING(y.n,2)) ELSE CONCAT(CASE WHEN y.n LIKE '% binti %' THEN 'Almarhumah' WHEN y.n LIKE '% bin %' THEN 'Almarhum' WHEN y.jk='L' THEN 'Almarhumah' WHEN y.jk='P' THEN 'Almarhum' ELSE 'Almarhum/Almarhumah' END,' ',IFNULL(y.n,'..................................................')) END AS data FROM (SELECT (SELECT NULLIF(TRIM(TRAILING ',' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(REPLACE(REPLACE(REPLACE(data,CHAR(13),' '),CHAR(10),' '),' ,',','))))),'') FROM aps_badilag.abt_data_teks WHERE no_var=1025 AND perkara_id=@pid LIMIT 1) AS n,(SELECT b.jenis_kelamin FROM perkara_pihak1 a JOIN pihak b ON a.pihak_id=b.id WHERE aps_badilag.isian_rtf_pihak_peringkat(1, a.id)=1 AND a.perkara_id=@pid LIMIT 1) AS jk) y) AS uji_9104;
