SELECT 9292 AS no_var, COUNT(*) AS baris FROM (SELECT IF(TRIM('0') REGEXP '^[0-9]{5}$' AND z.a NOT LIKE '%kode pos%' AND z.a NOT LIKE CONCAT('%', TRIM('0'), '%') AND LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM IF(z.m < 99999, LEFT(z.a, z.m - 1), z.a))))))))))) > 0, CONCAT(TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM IF(z.m < 99999, LEFT(z.a, z.m - 1), z.a)))))))))), ', Kode Pos ', TRIM('0'), IF(z.m < 99999, CONCAT('. ', TRIM(SUBSTRING(z.a, z.m))), '')), z.a) AS data FROM (SELECT x.a, LEAST(IFNULL(NULLIF(LOCATE('domisili elektronik', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('elektronik', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('email', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('e-mail', x.a), 0), 99999), IFNULL(NULLIF(IF(LOCATE('@', x.a) > 0, CHAR_LENGTH(LEFT(x.a, LOCATE('@', x.a) - 1)) - CHAR_LENGTH(SUBSTRING_INDEX(LEFT(x.a, LOCATE('@', x.a) - 1), ' ', -1)) + 1, 0), 0), 99999)) AS m FROM (SELECT aps_badilag.isian_rtf_alamat(IFNULL(p.alamat, '')) AS a FROM perkara_pihak1 p WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, p.id) = 1 LIMIT 1) x) z) AS uji_9292;
SELECT 9293 AS no_var, COUNT(*) AS baris FROM (SELECT IF(TRIM('0') REGEXP '^[0-9]{5}$' AND z.a NOT LIKE '%kode pos%' AND z.a NOT LIKE CONCAT('%', TRIM('0'), '%') AND LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM IF(z.m < 99999, LEFT(z.a, z.m - 1), z.a))))))))))) > 0, CONCAT(TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM TRIM(TRAILING '.' FROM TRIM(TRAILING ',' FROM TRIM(TRAILING ' ' FROM IF(z.m < 99999, LEFT(z.a, z.m - 1), z.a)))))))))), ', Kode Pos ', TRIM('0'), IF(z.m < 99999, CONCAT('. ', TRIM(SUBSTRING(z.a, z.m))), '')), z.a) AS data FROM (SELECT x.a, LEAST(IFNULL(NULLIF(LOCATE('domisili elektronik', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('elektronik', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('email', x.a), 0), 99999), IFNULL(NULLIF(LOCATE('e-mail', x.a), 0), 99999), IFNULL(NULLIF(IF(LOCATE('@', x.a) > 0, CHAR_LENGTH(LEFT(x.a, LOCATE('@', x.a) - 1)) - CHAR_LENGTH(SUBSTRING_INDEX(LEFT(x.a, LOCATE('@', x.a) - 1), ' ', -1)) + 1, 0), 0), 99999)) AS m FROM (SELECT aps_badilag.isian_rtf_alamat(IFNULL(p.alamat, '')) AS a FROM perkara_pihak2 p WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(2, p.id) = 1 LIMIT 1) x) z) AS uji_9293;
SELECT 9404 AS no_var, COUNT(*) AS baris FROM (SELECT CONCAT(IF(z.sisi = 1, "0", "0"), IF((z.sisi = 1 AND z.n1 > 1) OR (z.sisi = 2 AND z.n2 > 1), CONCAT(' ', IFNULL(ELT(z.u, 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'), z.u)), '')) AS data FROM (SELECT y.n1, y.n2, IF(y.f1 + y.f2 = 1, IF(y.f1 = 1, 1, 2), IF(y.jp = 346, 2, 1)) AS sisi, IF(y.f1 + y.f2 = 1, IF(y.f1 = 1, y.u1, y.u2), IF(y.jp IN (346, 347, 363), 1, IF(y.n1 >= 2, 2, 1))) AS u FROM (SELECT p.jenis_perkara_id AS jp, (SELECT COUNT(*) FROM perkara_pihak1 a WHERE a.perkara_id = p.perkara_id) AS n1, (SELECT COUNT(*) FROM perkara_pihak2 a WHERE a.perkara_id = p.perkara_id) AS n2, (SELECT COUNT(*) FROM perkara_pihak1 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS f1, (SELECT COUNT(*) FROM perkara_pihak2 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS f2, (SELECT MIN(aps_badilag.isian_rtf_pihak_peringkat(1, a.id)) FROM perkara_pihak1 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS u1, (SELECT MIN(aps_badilag.isian_rtf_pihak_peringkat(2, a.id)) FROM perkara_pihak2 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS u2 FROM perkara p WHERE p.perkara_id = @pid) y) z) AS uji_9404;
SELECT 9405 AS no_var, COUNT(*) AS baris FROM (SELECT TRIM(IF(LOCATE(' BINTI ', w.n) > 0, SUBSTRING(w.n, LOCATE(' BINTI ', w.n) + 7), IF(LOCATE(' BIN ', w.n) > 0, SUBSTRING(w.n, LOCATE(' BIN ', w.n) + 5), NULL))) AS data FROM (SELECT SUBSTRING_INDEX(REPLACE(CONCAT(' ', UPPER(TRIM(IFNULL(IF(z.sisi = 1, (SELECT a.nama FROM perkara_pihak1 a WHERE a.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, a.id) = z.u LIMIT 1), (SELECT a.nama FROM perkara_pihak2 a WHERE a.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(2, a.id) = z.u LIMIT 1)), ''))), ' '), '  ', ' '), ' ALIAS ', 1) AS n FROM (SELECT y.n1, y.n2, IF(y.f1 + y.f2 = 1, IF(y.f1 = 1, 1, 2), IF(y.jp = 346, 2, 1)) AS sisi, IF(y.f1 + y.f2 = 1, IF(y.f1 = 1, y.u1, y.u2), IF(y.jp IN (346, 347, 363), 1, IF(y.n1 >= 2, 2, 1))) AS u FROM (SELECT p.jenis_perkara_id AS jp, (SELECT COUNT(*) FROM perkara_pihak1 a WHERE a.perkara_id = p.perkara_id) AS n1, (SELECT COUNT(*) FROM perkara_pihak2 a WHERE a.perkara_id = p.perkara_id) AS n2, (SELECT COUNT(*) FROM perkara_pihak1 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS f1, (SELECT COUNT(*) FROM perkara_pihak2 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS f2, (SELECT MIN(aps_badilag.isian_rtf_pihak_peringkat(1, a.id)) FROM perkara_pihak1 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS u1, (SELECT MIN(aps_badilag.isian_rtf_pihak_peringkat(2, a.id)) FROM perkara_pihak2 a JOIN pihak b ON b.id = a.pihak_id WHERE a.perkara_id = p.perkara_id AND b.jenis_kelamin = 'P') AS u2 FROM perkara p WHERE p.perkara_id = @pid) y) z) w) AS uji_9405;
SELECT 9560 AS no_var, COUNT(*) AS baris FROM (SELECT x.data FROM (SELECT COALESCE((SELECT r.provinsi_nama FROM ref_provinsi_new r WHERE r.provinsi_kode = TRIM(b.propinsi) LIMIT 1), (SELECT r.provinsi_nama FROM ref_provinsi_new r JOIN ref_kabupaten_new k ON k.provinsi_kode = r.provinsi_kode WHERE k.kabupaten_kode = TRIM(b.kabupaten) LIMIT 1), NULLIF(TRIM(b.propinsi), '')) AS data FROM perkara_pihak2 p JOIN pihak b ON b.id = p.pihak_id WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(2, p.id) = 1 LIMIT 1) x WHERE IFNULL(x.data, '') <> '') AS uji_9560;
SELECT 9561 AS no_var, COUNT(*) AS baris FROM (SELECT x.data FROM (SELECT COALESCE((SELECT k.kabupaten_nama FROM ref_kabupaten_new k WHERE k.kabupaten_kode = TRIM(b.kabupaten) LIMIT 1), (SELECT k.kabupaten_nama FROM ref_kabupaten_new k WHERE k.kabupaten_nama IN (TRIM(b.kabupaten), CONCAT('Kabupaten ', TRIM(b.kabupaten)), CONCAT('Kota ', TRIM(b.kabupaten)), CONCAT('Kabupaten ', TRIM(SUBSTRING(TRIM(b.kabupaten), 5))), CONCAT('Kabupaten ', TRIM(SUBSTRING(TRIM(b.kabupaten), 4)))) LIMIT 1), IF(TRIM(b.kabupaten) LIKE 'Kab.%', CONCAT('Kabupaten ', TRIM(SUBSTRING(TRIM(b.kabupaten), 5))), NULLIF(TRIM(b.kabupaten), ''))) AS data FROM perkara_pihak1 p JOIN pihak b ON b.id = p.pihak_id WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, p.id) IN (1, 2) AND TRIM(IFNULL(b.kabupaten, '')) <> '' ORDER BY p.urutan DESC LIMIT 1) x WHERE IFNULL(x.data, '') <> '') AS uji_9561;
SELECT 9562 AS no_var, COUNT(*) AS baris FROM (SELECT x.data FROM (SELECT COALESCE((SELECT r.provinsi_nama FROM ref_provinsi_new r WHERE r.provinsi_kode = TRIM(b.propinsi) LIMIT 1), (SELECT r.provinsi_nama FROM ref_provinsi_new r JOIN ref_kabupaten_new k ON k.provinsi_kode = r.provinsi_kode WHERE k.kabupaten_kode = TRIM(b.kabupaten) LIMIT 1), NULLIF(TRIM(b.propinsi), '')) AS data FROM perkara_pihak1 p JOIN pihak b ON b.id = p.pihak_id WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, p.id) IN (1, 2) AND (TRIM(IFNULL(b.propinsi, '')) <> '' OR TRIM(IFNULL(b.kabupaten, '')) <> '') ORDER BY p.urutan DESC LIMIT 1) x WHERE IFNULL(x.data, '') <> '') AS uji_9562;
SELECT 10106 AS no_var, COUNT(*) AS baris FROM (-- Bawaan 0 = status pihak PERTAMA sebelum menikah (keputusan 14 Okt 2026 butir 1).
-- Jenis kelamin pihak menurut SIPP (pihak.jenis_kelamin P/L), lalu nama ber-"binti"/"bin"; tanpa keduanya: cerai gugat = perempuan.
-- Perempuan: Janda Cerai Mati / Janda Cerai Hidup / Janda / Perawan; laki-laki: Duda Cerai Mati / Duda Cerai Hidup / Duda / Jejaka.
SELECT CASE WHEN x.wanita = 1 THEN
  CASE WHEN x.t REGEXP 'JANDA CERAI MATI|JANDA MATI|JANDA DITINGGAL MATI' THEN 'Janda Cerai Mati'
       WHEN x.t REGEXP 'JANDA CERAI' THEN 'Janda Cerai Hidup'
       WHEN x.t REGEXP '[[:<:]]JANDA[[:>:]]' THEN 'Janda'
       WHEN x.t REGEXP '[[:<:]](PERAWAN|GADIS|DARA)[[:>:]]' THEN 'Perawan'
       ELSE NULL END
ELSE
  CASE WHEN x.t REGEXP 'DUDA CERAI MATI|DUDA MATI|DUDA DITINGGAL MATI' THEN 'Duda Cerai Mati'
       WHEN x.t REGEXP 'DUDA CERAI' THEN 'Duda Cerai Hidup'
       WHEN x.t REGEXP '[[:<:]]DUDA[[:>:]]' THEN 'Duda'
       WHEN x.t REGEXP '[[:<:]](PERJAKA|JEJAKA|LAJANG|BUJANG)[[:>:]]' THEN 'Jejaka'
       ELSE NULL END
END AS data
FROM (
  SELECT UPPER(CONVERT(IFNULL(p.posita, '') USING utf8)) AS t,
    CASE WHEN h.jenis_kelamin = 'P' THEN 1 WHEN h.jenis_kelamin = 'L' THEN 0
         WHEN CONCAT(' ', IFNULL(h.nama, ''), ' ') LIKE '% binti %' THEN 1
         WHEN CONCAT(' ', IFNULL(h.nama, ''), ' ') LIKE '% bin %' THEN 0
         WHEN p.jenis_perkara_id = 347 THEN 1 ELSE 0 END AS wanita
  FROM perkara p
    LEFT JOIN perkara_pihak1 a ON a.perkara_id = p.perkara_id AND aps_badilag.isian_rtf_pihak_peringkat(1, a.id) = 1
    LEFT JOIN pihak h ON h.id = a.pihak_id
  WHERE p.perkara_id = @pid
  LIMIT 1
) x) AS uji_10106;
SELECT 10107 AS no_var, COUNT(*) AS baris FROM (-- Bawaan 0 = status pihak KEDUA sebelum menikah (keputusan 14 Okt 2026 butir 1): Pemohon II pada permohonan,
-- pihak lawan (Tergugat/Termohon) pada gugatan. Jenis kelamin menurut SIPP (pihak.jenis_kelamin P/L), lalu "binti"/"bin";
-- tanpa keduanya: cerai gugat = laki-laki, lainnya = perempuan.
SELECT CASE WHEN x.wanita = 1 THEN
  CASE WHEN x.t REGEXP 'JANDA CERAI MATI|JANDA MATI|JANDA DITINGGAL MATI' THEN 'Janda Cerai Mati'
       WHEN x.t REGEXP 'JANDA CERAI' THEN 'Janda Cerai Hidup'
       WHEN x.t REGEXP '[[:<:]]JANDA[[:>:]]' THEN 'Janda'
       WHEN x.t REGEXP '[[:<:]](PERAWAN|GADIS|DARA)[[:>:]]' THEN 'Perawan'
       ELSE NULL END
ELSE
  CASE WHEN x.t REGEXP 'DUDA CERAI MATI|DUDA MATI|DUDA DITINGGAL MATI' THEN 'Duda Cerai Mati'
       WHEN x.t REGEXP 'DUDA CERAI' THEN 'Duda Cerai Hidup'
       WHEN x.t REGEXP '[[:<:]]DUDA[[:>:]]' THEN 'Duda'
       WHEN x.t REGEXP '[[:<:]](PERJAKA|JEJAKA|LAJANG|BUJANG)[[:>:]]' THEN 'Jejaka'
       ELSE NULL END
END AS data
FROM (
  SELECT UPPER(CONVERT(IFNULL(p.posita, '') USING utf8)) AS t,
    CASE WHEN h.jenis_kelamin = 'P' THEN 1 WHEN h.jenis_kelamin = 'L' THEN 0
         WHEN CONCAT(' ', IFNULL(h.nama, ''), ' ') LIKE '% binti %' THEN 1
         WHEN CONCAT(' ', IFNULL(h.nama, ''), ' ') LIKE '% bin %' THEN 0
         WHEN p.jenis_perkara_id = 347 THEN 0 ELSE 1 END AS wanita
  FROM perkara p
    LEFT JOIN pihak h ON h.id = IF(p.alur_perkara_id = 16,
      (SELECT a.pihak_id FROM perkara_pihak1 a WHERE a.perkara_id = p.perkara_id AND aps_badilag.isian_rtf_pihak_peringkat(1, a.id) = 2 LIMIT 1),
      (SELECT a.pihak_id FROM perkara_pihak2 a WHERE a.perkara_id = p.perkara_id ORDER BY a.urutan LIMIT 1))
  WHERE p.perkara_id = @pid
  LIMIT 1
) x) AS uji_10107;
